import{_ as r,o,c as e,a2 as s}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"外觀與主題","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/appearance.md","filePath":"zh-TW/user-guide/settings/appearance.md","lastUpdated":1787586465000}'),a={name:"zh-TW/user-guide/settings/appearance.md"};function n(i,t,l,g,d,h){return o(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="外觀與主題" tabindex="-1">外觀與主題 <a class="header-anchor" href="#外觀與主題" aria-label="Permalink to &quot;外觀與主題&quot;">​</a></h1><p>Lertaro 提供了高顏值的現代化介面設計體系，支援精細化的主題模式切換與豐富的配色方案。外觀設定頁面位於設定中心左側側邊欄底部（「關於」上方）。</p><h2 id="_1-主題模式-theme-modes" tabindex="-1">1. 主題模式（Theme Modes） <a class="header-anchor" href="#_1-主題模式-theme-modes" aria-label="Permalink to &quot;1. 主題模式（Theme Modes）&quot;">​</a></h2><p>頁面頂部提供三種主題模式切換卡片，按一下即可瞬間切換生效：</p><ul><li><strong>淺色模式（Light）</strong>：固定使用淺色調介面風格，下方的主題選取網格將僅展示淺色風格的主題卡片。</li><li><strong>深色模式（Dark）</strong>：固定使用深色調介面風格，下方網格將僅展示深色風格的主題卡片。</li><li><strong>跟隨系統（Follow System）</strong>：介面將根據 Windows 系統的深淺色設定自動即時切換。在此模式下，下方網格會分別呈現<strong>淺色主題</strong>與<strong>深色主題</strong>兩個選取區，你可以為白天和黑夜分別指定心儀的配色方案，系統切換時無需重啟 Lertaro 即可平滑過渡。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Lertaro 會獨立記憶你在淺色與深色模式下分別選取的主題。當你在不同模式之間切換時，已選定的配色方案絕不會遺失。</p></div><h2 id="_2-介面主題選取卡片" tabindex="-1">2. 介面主題選取卡片 <a class="header-anchor" href="#_2-介面主題選取卡片" aria-label="Permalink to &quot;2. 介面主題選取卡片&quot;">​</a></h2><p>主題選取區採用視覺化的縮圖卡片網格呈現，每張卡片都真實反映了搜尋框、邊框陰影、文字層級與選取反白行的實際配色效果，目前生效的主題右上角帶有清晰的勾選徽標。</p><h3 id="內建與隨包主題介紹" tabindex="-1">內建與隨包主題介紹 <a class="header-anchor" href="#內建與隨包主題介紹" aria-label="Permalink to &quot;內建與隨包主題介紹&quot;">​</a></h3><ul><li><strong>核心內建主題（CoreExtensions）</strong>： <ul><li><strong>淺色（Light）</strong> / <strong>深色（Dark）</strong>：經典簡約的黑白基底設計，完美融入 Windows 原生系統風格。</li><li><strong>北歐藍（Nordic Blue）</strong>：冷色調極簡極客風，低飽和度的冰藍與深海背景。</li><li><strong>櫻花粉（Sakura Pink）</strong>：柔和清新的粉白配色，細膩優雅。</li><li><strong>賽博龐克（Cyberpunk）</strong>：高對比度的霓虹黃與深紫夜色，充滿未來科技感。</li></ul></li><li><strong>動漫主題包（AnimeThemes，隨包提供）</strong>： <ul><li><strong>新世紀（Evangelion）</strong>、<strong>櫻花盛開（Sakura Blossom）</strong>、<strong>天氣之子（Weathering with You）</strong>。</li></ul></li><li><strong>臻選成對主題（Curated Themes，隨包提供）</strong>： <ul><li>精心調配的 10 組淺色 / 深色成對主題：<strong>冰川藍（Glacier Blue）</strong>、<strong>陶土棕（Terracotta）</strong>、<strong>森林綠（Forest Green）</strong>、<strong>紫水晶（Amethyst）</strong>、<strong>緋紅（Crimson）</strong>、<strong>石墨灰（Graphite）</strong>、<strong>靛藍夜（Indigo Night）</strong>、<strong>薄荷青（Mint Cyan）</strong>、<strong>香檳金（Champagne Gold）</strong>、<strong>琥珀金（Amber Gold）</strong>。</li></ul></li></ul><h3 id="外掛模組主題擴充能力" tabindex="-1">外掛模組主題擴充能力 <a class="header-anchor" href="#外掛模組主題擴充能力" aria-label="Permalink to &quot;外掛模組主題擴充能力&quot;">​</a></h3><p>所有主題均基於 <code>Lertaro.PluginSdk</code> 的 UI 主題標準規範開發。第三方開發者可以透過編寫主題外掛模組向此網格動態註冊全新的個人化配色方案。</p>',12)])])}const p=r(a,[["render",n]]);export{c as __pageData,p as default};
